use crate::*;
use crate::owned::NativeRecordStorage;
use semio_framework_value_testing_admission::Wallet;
fn law()->serde_json::Value{serde_json::from_str(include_str!("../📐️.json")).unwrap()}
fn clear(actual:&mut Option<usize>,bank:&mut Wallet){if actual.is_some(){let g=bank.loan(1,32768);let copy=std::mem::size_of::<Option<usize>>();assert!(g.maximum_copy_bytes>=copy&&bank.work_remaining()>=1);*actual=None;bank.post(RetainedCloneProgress{copied_items:1,copied_bytes:copy,..Default::default()},1,g,(0,0));}}
fn post(bank:&mut Wallet,turn:RetainedWorkOutcome,grant:RetainedCloneGrant,heap:(usize,usize))->RetainedCloneProgress{let p=turn.result.unwrap().progress();assert!(turn.work<=bank.work_remaining());bank.post(p,turn.work,grant,heap);p}
#[test]
fn actual_native_record_typed_backing_keeps_null_uninitialized_and_taken_ownership(){
 let law=law();let abi=law["abiCases"].as_array().unwrap().iter().find(|r|r["wordBytes"].as_u64().unwrap()as usize==std::mem::size_of::<usize>()).unwrap();let mut bank=Wallet::from_profile(&law["stock"]);let mut owner=NativeRecordStorage::<u64>::empty(1);let mut actual=None;let g=bank.loan(1,32768);
 assert_eq!(owner.reserve(RetainedCloneGrant{maximum_items:0,..g},&mut actual).work,0);assert!(actual.is_none());
 let((turn,attempts),heap)=crate::observe_retirement_allocations(||semio_framework_value_testing_allocator::refuse_one_allocation_on_this_thread(||owner.reserve(g,&mut actual)));assert_eq!(attempts,1);assert_eq!(actual,Some(0));assert_eq!(heap,(0,0));assert_eq!(turn.work,1);let p=turn.result.err().unwrap().retained_progress();bank.post(p,turn.work,g,heap);assert!(!owner.reserved());clear(&mut actual,&mut bank);
 let g=bank.loan(1,32768);let(turn,heap)=crate::observe_retirement_allocations(||owner.reserve(g,&mut actual));assert_eq!(turn.work,law["allocationWork"].as_u64().unwrap());let p=post(&mut bank,turn,g,heap);assert_eq!(actual,Some(p.retained_capacity_bytes));clear(&mut actual,&mut bank);
 let g=bank.loan(1,32768);let(turn,heap)=crate::observe_retirement_allocations(||owner.initialize(g));assert_eq!(turn.work,law["initializeWork"].as_u64().unwrap());let p=post(&mut bank,turn,g,heap);assert_eq!(p.copied_bytes,1);
 let mut value=Some(law["value"].as_u64().unwrap());let d=NativeRecordStorage::<u64>::place_field_demand::<u64>();assert_eq!(d.copy_bytes,abi["fieldCopy"].as_u64().unwrap()as usize);
 for denied in [RetainedCloneGrant{maximum_items:0,..g},RetainedCloneGrant{maximum_copy_bytes:d.copy_bytes-1,..g}]{let turn=unsafe{owner.place_field(0,&mut value,denied)};assert_eq!(turn.work,0);assert!(turn.result.unwrap().is_none());assert_eq!(value,Some(42))}
 let g=bank.loan(1,32768);let(turn,heap)=crate::observe_retirement_allocations(||unsafe{owner.place_field(0,&mut value,g)});assert_eq!(turn.work,law["placeWork"].as_u64().unwrap());let p=turn.result.unwrap().unwrap();assert_eq!(p.copied_bytes,d.copy_bytes);bank.post(p,turn.work,g,heap);assert!(value.is_none());

 let pointer=owner.backing_address();let remove=NativeRecordStorage::<u64>::remove_field_demand::<u64>();let mut removed=None;let g=bank.loan(1,32768);let denied=unsafe{owner.remove_field(0,&mut removed,RetainedCloneGrant{maximum_copy_bytes:remove.copy_bytes-1,..g})};assert_eq!(denied.work,0);assert_eq!(denied.result.unwrap().progress(),Default::default());assert!(removed.is_none());
 let(turn,heap)=crate::observe_retirement_allocations(||unsafe{owner.remove_field(0,&mut removed,g)});assert_eq!(turn.work,law["removeWork"].as_u64().unwrap());let p=post(&mut bank,turn,g,heap);assert_eq!(p.copied_bytes,abi["fieldCopy"].as_u64().unwrap()as usize);assert_eq!(removed,Some(42));assert_eq!(owner.backing_address(),pointer);
 let g=bank.loan(1,32768);let incomplete=unsafe{owner.take_initialized(g)};assert!(incomplete.result.is_err());assert_eq!(incomplete.work,0);let(turn,heap)=crate::observe_retirement_allocations(||unsafe{owner.place_field(0,&mut removed,g)});let p=turn.result.unwrap().unwrap();bank.post(p,turn.work,g,heap);assert!(removed.is_none());

 let g=bank.loan(1,32768);let denied=unsafe{owner.take_initialized(RetainedCloneGrant{maximum_items:0,..g})};assert_eq!(denied.work,0);assert!(denied.result.unwrap().is_none());
 let(turn,heap)=crate::observe_retirement_allocations(||unsafe{owner.take_initialized(g)});assert_eq!(turn.work,law["takeWork"].as_u64().unwrap());let(output,p)=turn.result.unwrap().unwrap();assert_eq!(serde_json::to_value(output).unwrap(),law["value"]);assert_eq!(p.copied_bytes,abi["takeCopy"].as_u64().unwrap()as usize);bank.post(p,turn.work,g,heap);assert_eq!(unsafe{owner.take_initialized(Default::default())}.work,0);
 let g=bank.loan(1,32768);let(turn,heap)=crate::observe_retirement_allocations(||owner.release(g));assert_eq!(turn.work,law["releaseWork"].as_u64().unwrap());let p=post(&mut bank,turn,g,heap);assert_eq!(p.copied_bytes,abi["releaseCopy"].as_u64().unwrap()as usize);assert!(owner.terminal_is_empty());assert!(bank.work_remaining()<law["stock"]["fuel"].as_u64().unwrap());
}
#[test]
fn complete_record_transfers_original_backing_without_moving_value(){
 let law=law();let f:serde_json::Value=serde_json::from_str(include_str!("🧫️handoff/🔣️.json")).unwrap();assert_eq!(f["cases"].as_array().unwrap().iter().find(|r|r["fields"]==2&&r["initialized"]==1).unwrap()["canCommit"],false);let abi=law["abiCases"].as_array().unwrap().iter().find(|r|r["wordBytes"].as_u64().unwrap()as usize==std::mem::size_of::<usize>()).unwrap();let mut bank=Wallet::from_profile(&law["stock"]);let mut record=NativeRecordStorage::<u64>::empty(1);let mut actual=None;
 let g=bank.loan(1,32768);let(turn,heap)=crate::observe_retirement_allocations(||record.reserve(g,&mut actual));let p=post(&mut bank,turn,g,heap);assert_eq!(actual,Some(p.retained_capacity_bytes));clear(&mut actual,&mut bank);
 let g=bank.loan(1,32768);let(turn,heap)=crate::observe_retirement_allocations(||record.initialize(g));post(&mut bank,turn,g,heap);let pointer=record.backing_address().unwrap();
 let turn=unsafe{record.take_box_initialized(g,law["takeWork"].as_u64().unwrap())};assert!(turn.result.is_err());assert_eq!(record.backing_address(),Some(pointer));
 let mut value=Some(law["value"].as_u64().unwrap());let g=bank.loan(1,32768);let(turn,heap)=crate::observe_retirement_allocations(||unsafe{record.place_field(0,&mut value,g)});let p=turn.result.unwrap().unwrap();bank.post(p,turn.work,g,heap);
 let g=bank.loan(1,32768);let required=NativeRecordStorage::<u64>::take_box_initialized_work_demand();let denied=unsafe{record.take_box_initialized(g,required-1)};assert_eq!(denied.work,0);assert!(denied.result.unwrap().is_none());assert_eq!(record.backing_address(),Some(pointer));
 let(turn,heap)=crate::observe_retirement_allocations(||unsafe{record.take_box_initialized(g,required)});assert_eq!(turn.work,law["takeWork"].as_u64().unwrap());let(output,p)=turn.result.unwrap().unwrap();assert_eq!((&*output as*const u64)as usize,pointer);assert_eq!(*output,42);assert_eq!(p.copied_bytes,abi["boxCopy"].as_u64().unwrap()as usize);assert_eq!(heap,(0,0));bank.post(p,turn.work,g,heap);assert!(record.taken());assert!(record.terminal_is_empty());semio_framework_value_testing_admission::close_owned(output,&mut bank,32768,256);
}
